input.new_string:
variable {a n : ℕ} {K : Submodule R (relThetaSections C R pi a)}
variable {D : ThetaGeneratorSeed C R pi a K}

/- The curve instances are carried by the seed's own data; none of the declarations
below re-derives geometry from them. -/
omit [IsProper C.hom] [SmoothOfRelativeDimension 1 C.hom]
  [GeometricallyIrreducible C.hom]

input.command:
cd "$ARCHON_HORIZON_ROOT" && for q in "DivisorAdaptation pullback away localization pieces" "adaptation.pullback IsCertified" "pulledEquations pullback relCurveMap DivEq"; do echo "### $q"; "$HORIZON_BIN" search "$q" --json 2>/dev/null | python3 -c "
import json,sys
for r in json.load(sys.stdin)[:7]:
  if r['library']!='mathlib': print(' ',r['name'],'|',r['file'].split('/')[-1],r['line']); print('     ',r['signature'][:250])
"; done
